package orders // one package per table

type Row struct {
	ID    int64
	Due   time.Time
	Total float64
}

func Overdue(ctx context.Context, db *sql.DB, asOf time.Time) ([]Row, error) {
	rows, err := db.QueryContext(ctx, `SELECT id, due, total FROM orders WHERE due < $1`, asOf)
	if err != nil { return nil, err }
	defer rows.Close()
	var out []Row
	for rows.Next() { var r Row; if err := rows.Scan(&r.ID, &r.Due, &r.Total); err != nil { return nil, err }; out = append(out, r) }
	return out, rows.Err()
}
